<!-- Client-side Interactive Filter Script -->
<script>
    function filterFacilities(category, triggerBtn) {
      // Button states
      const allButtons = document.querySelectorAll('#filterBtnGroup .facility-filter');
      allButtons.forEach(btn => {
        btn.classList.remove('bg-primary', 'text-on-primary', 'shadow-sm');
        btn.classList.add('bg-surface-container-low', 'text-on-surface');
      });
      triggerBtn.classList.remove('bg-surface-container-low', 'text-on-surface');
      triggerBtn.classList.add('bg-primary', 'text-on-primary', 'shadow-sm');

      // Card items visibility
      const items = document.querySelectorAll('#facilityCardsContainer .facility-item');
      items.forEach(card => {
        if (category === 'all' || card.classList.contains(category)) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    }
  </script>
